<script setup lang="ts">
import {ref,watch,onBeforeUnmount,nextTick} from 'vue'
import {pointStudyApi,teachers,type PointStudy} from '@/api/coaching'
import {learningApi} from '@/api/learning'
import {messageOf} from '@/api/client'
import type {Citation,ChatResult,KnowledgeBase} from '@/api/types'
import type {Asset} from '@/api/foundation'
import SafeAnswer from '@/components/SafeAnswer.vue'
import SpeakButton from '@/components/SpeakButton.vue'
import CitationReader from '@/components/CitationReader.vue'
const props=defineProps<{pointId:string}>(),emit=defineEmits<{select:[id:string]}>()
const data=ref<PointStudy>(),loading=ref(false),error=ref(''),teacher=ref('encouraging'),bases=ref<KnowledgeBase[]>([]),kb=ref(''),teaching=ref(false),lesson=ref<ChatResult|null>(null),teachError=ref(''),source=ref<Citation|null>(null),exampleOpen=ref(false)
const teacherArea=ref<HTMLElement|null>(null)
let request=0
async function load(){const id=++request;loading.value=true;error.value='';data.value=undefined;lesson.value=null;source.value=null;exampleOpen.value=false;teachError.value='';teaching.value=false
 try{const pack=await pointStudyApi.load(props.pointId);if(id===request){data.value=pack;if(pack.PreferredKnowledgeBaseID&&bases.value.some(b=>b.ID===pack.PreferredKnowledgeBaseID))kb.value=pack.PreferredKnowledgeBaseID}}catch(e){if(id===request)error.value=messageOf(e)}finally{if(id===request)loading.value=false}
}
watch(()=>props.pointId,()=>load(),{immediate:true})
async function prepareBases(){try{bases.value=await learningApi.bases();kb.value=bases.value.find(b=>b.ID===data.value?.PreferredKnowledgeBaseID)?.ID??bases.value.find(b=>b.IsPublic)?.ID??bases.value[0]?.ID??''}catch(e){teachError.value='教材内容仍可阅读；讲解资料范围读取失败：'+messageOf(e)}}
prepareBases()
async function teach(example?:Asset){if(!kb.value||!data.value)return;const id=request;teaching.value=true;teachError.value='';lesson.value=null
 if(example){await nextTick();teacherArea.value?.scrollIntoView({block:'nearest'})}
 const style=teachers.find(t=>t.id===teacher.value)?.hint??''
 const question=example?`请用老师口吻讲清这道例题：${example.Payload.Stem}\n选项：${example.Payload.Options.join('；')}\n原文解析：${example.Payload.Explanation}\n按条件、解题依据、推导、结论逐步讲解，不猜改公式。`:`请讲解${data.value.Point.Name}。先解释定义、适用条件，再解释概念之间的联系和易错点；适合正在复习的学生，不能只列名词。`
 try{const answer=await learningApi.chat(kb.value,'',question+'\n风格：'+style+'只根据教材证据讲解，资料不足明确说明，来源放在正文之后。');if(id===request)lesson.value=answer}catch(e){if(id===request)teachError.value='老师讲解暂未完成，可先核对下方教材及原文解析：'+messageOf(e)}finally{if(id===request)teaching.value=false}
}
function exampleSource(q:Asset){if(!q.Payload.DocumentID)return;source.value={DocumentID:q.Payload.DocumentID,DocumentTitle:q.Payload.Source,ChunkID:'',Location:q.Payload.Page?`第${q.Payload.Page}页`:'题目来源',Page:q.Payload.Page,Excerpt:q.Payload.Stem,Score:1}}
onBeforeUnmount(()=>request++)
</script>
<template><section class="point-study" aria-label="知识点学习内容"><p v-if="loading" role="status">正在定位教材、错题与练习…</p><p v-if="error" class="notice error" role="alert">{{error}} <button class="secondary" @click="load">重试</button></p><template v-if="data">
<div v-if="data.Ancestors.length" class="path"><span>知识目录：</span><button v-for="p in data.Ancestors" :key="p.ID" class="text-link" @click="emit('select',p.ID)">{{p.Name}} ›</button><b>{{data.Point.Name}}</b></div>
<p class="coverage">本点 {{data.DirectQuestions}} 个可靠题组 · 含下级共 {{data.SubtreeQuestions}} 个；当前可选新练习 {{data.Exercises.length}} 题。</p>
<details v-if="data.Children.length"><summary>继续细分学习（{{data.Children.length}} 个下级知识点）</summary><div class="actions"><button v-for="child in data.Children" :key="child.ID" class="secondary" @click="emit('select',child.ID)">{{child.Name}}</button></div></details>
<section class="study-section"><h3>先复查：最近有效错题</h3><p v-if="!data.Mistakes.length" class="muted">本点及下级暂无当前有效错题记录；这不代表全部掌握，未测内容仍需诊断。</p><details v-for="(wrong,n) in data.Mistakes" :open="n===0" :key="wrong.AssessmentID+wrong.Question.ID"><summary>{{wrong.Question.Title}}</summary><p class="stem">{{wrong.Question.Payload.Stem}}</p><p v-if="data.PointNames?.[wrong.Question.PointID]" class="muted">所属知识点：{{data.PointNames[wrong.Question.PointID]}}</p><p v-for="(o,i) in wrong.Question.Payload.Options" :key="i">{{String.fromCharCode(65+i)}}. {{o}}</p><img v-for="(img,i) in wrong.Question.Payload.Images??[]" :key="i" :src="img" alt="错题原图"/><p>你的答案：{{wrong.Result.Selected<0?'未掌握 / 不确定':String.fromCharCode(65+wrong.Result.Selected)}} · 参考答案：{{wrong.Result.Answer<0?'尚无可核对答案':String.fromCharCode(65+wrong.Result.Answer)}}</p><p v-if="wrong.Result.AnswerOrigin&&wrong.Result.AnswerOrigin!=='source'" class="muted">本次记录含用户确认或AI辅助判断，并非资料标准答案，请结合原文核对。</p><SafeAnswer :text="wrong.Result.Explanation"/><RouterLink class="secondary" :to="{path:'/exam408/assessment',query:{assessment:wrong.AssessmentID}}">查看完整报告与题目</RouterLink></details></section>
<section class="study-section"><h3>教材复习与老师讲解</h3><p class="muted">目录描述只说明范围；以下教材摘录才是可核对的学习依据。</p><p v-if="!data.Knowledge.length" class="muted">{{data.Missing.find(s=>s.includes('教材'))??'暂未定位到教材段落。'}} 可以选择下级知识点继续查找。</p><details v-for="(c,n) in data.Knowledge" :key="c.ChunkID" :open="n===0"><summary>{{c.DocumentTitle}} · {{c.Location||`第${c.Page}页`}}</summary><p class="stem">{{c.Excerpt}}</p><button class="secondary" @click="source=c">查看教材原文</button></details>
<div ref="teacherArea" class="teacher-controls"><label>讲解风格<select v-model="teacher" :disabled="teaching"><option v-for="t in teachers" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>资料范围<select v-model="kb" :disabled="teaching"><option v-for="b in bases" :key="b.ID" :value="b.ID">{{b.Name}}{{b.IsPublic?'':' ＋ 公共教材'}}</option></select></label><button class="primary" :disabled="teaching||!kb" @click="teach()">{{teaching?'老师正在整理…':'请老师在这里讲解'}}</button></div><p v-if="teaching" role="status">老师正在检索教材并整理讲解，原文与练习仍可查看。</p><p v-if="!kb" class="muted">暂无可用的讲解知识库，请先检查资料知识库。</p><p v-if="teachError" class="notice error" role="alert">{{teachError}}</p><article v-if="lesson" class="teacher-answer"><p v-if="lesson.Generation&&!lesson.Generation.Verified" class="muted">本次尚未形成通过核验的老师讲解，以下保留服务返回的教材或诊断信息，请核对来源。</p><SafeAnswer :text="lesson.Answer" :citations="lesson.Sources.length" @cite="n=>source=lesson!.Sources[n]??null"/><SpeakButton :key="pointId+lesson.ConversationID" :text="lesson.Answer"/><details v-if="lesson.Sources.length"><summary>讲解来源</summary><button v-for="(c,n) in lesson.Sources" :key="n" class="secondary" @click="source=c">{{c.DocumentTitle}} · {{c.Location||`第${c.Page}页`}}</button></details></article></section>
<section class="study-section"><h3>例题：看清解题依据</h3><p v-if="!data.Example" class="muted">{{data.Missing.find(s=>s.includes('例题'))??'暂无有可靠答案与解析的参考例题。'}} 可先阅读教材或复查已有错题。</p><template v-else><p v-if="data.Example.PointID!==pointId" class="muted">例题所属知识点：{{data.PointNames?.[data.Example.PointID]??'下级概念'}}</p><p class="stem">{{data.Example.Payload.Stem}}</p><p v-for="(o,n) in data.Example.Payload.Options" :key="n">{{String.fromCharCode(65+n)}}. {{o}}</p><img v-for="(img,n) in data.Example.Payload.Images??[]" :key="n" :src="img" alt="例题原图"/><div class="actions"><button class="secondary" @click="exampleOpen=!exampleOpen">{{exampleOpen?'收起解析':'查看例题答案与原文解析'}}</button><button class="secondary" :disabled="teaching||!kb" @click="teach(data.Example)">老师逐步讲这道题</button><button v-if="data.Example.Payload.DocumentID" class="secondary" @click="exampleSource(data.Example)">查看例题原文</button></div><div v-if="exampleOpen"><p>参考答案：{{String.fromCharCode(65+data.Example.Payload.Answer)}}</p><SafeAnswer :text="data.Example.Payload.Explanation"/><small>{{data.Example.Payload.Source}}</small></div></template></section>
<section class="study-section"><h3>再练习：独立完成新题</h3><p>练习与例题分开；提交后查看解析，作答结果会更新学情。</p><p v-if="!data.Exercises.length" class="muted">暂无未接触的可靠练习题组；可先复查错题。已有题目不冒充新题。</p><RouterLink v-for="q in data.Exercises" :key="q.ID" class="practice-link" :to="{path:'/exam408/assessment',query:{point:q.PointID,asset:q.ID}}"><b>{{q.Title}}</b><span>{{q.Payload.Stem}}</span><small>{{data.PointNames?.[q.PointID]??(q.PointID===pointId?'当前知识点':'下级知识点练习')}} · {{q.Payload.Source}}</small><strong>开始作答 →</strong></RouterLink><div class="actions"><RouterLink v-if="data.DirectQuestions>0||data.Example" class="secondary" :to="{path:'/exam408/tasks',query:{tab:'teacher',point:data.DirectQuestions>0?pointId:data.Example?.PointID}}">{{data.DirectQuestions>0?'进入随堂教学与提问':'进入例题知识点的随堂教学'}}</RouterLink><RouterLink v-if="data.DirectQuestions>0||data.Example" class="secondary" :to="{path:'/exam408/assets',query:{point:data.DirectQuestions>0?pointId:data.Example?.PointID}}">{{data.DirectQuestions>0?'查看本点题库':'查看例题知识点题库'}}</RouterLink><RouterLink class="secondary" to="/exam408/tasks">查看复习单元与新题检查</RouterLink></div></section>
</template><CitationReader :source="source" @close="source=null"/></section></template>
<style scoped>.point-study{min-width:0;overflow-wrap:anywhere}.study-section{padding:20px 0;border-bottom:1px solid #e2e8f0}.study-section h3{margin-top:0}.coverage{background:#eff6ff;padding:12px;border-radius:9px}.point-study details{padding:12px;margin:10px 0;background:#f8fafc;border-radius:10px}.point-study summary{cursor:pointer;font-weight:600}.stem{white-space:pre-wrap;line-height:1.9}.point-study img{max-width:100%;max-height:400px;object-fit:contain}.actions,.path{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.text-link{border:0;background:none;color:#2563eb;padding:0}.teacher-controls{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.teacher-controls label{display:grid;gap:6px;flex:1;min-width:150px}.teacher-controls select{width:100%;min-width:0}.teacher-answer{padding:16px;background:#fff;border:1px solid #dbeafe;border-radius:12px;margin-top:16px}.practice-link{display:grid;gap:8px;border:1px solid #dbeafe;padding:16px;border-radius:12px;margin:12px 0;color:#26374c}.practice-link span{white-space:pre-wrap}.practice-link strong{color:#2563eb}.point-study .secondary{max-width:100%}@media(max-width:600px){.teacher-controls{display:grid}.teacher-controls label{min-width:0}}</style>
